import sys

def can_make_equal(a, b):
    from collections import Counter

    # Count the frequency of each element in both multisets
    count_a = Counter(a)
    count_b = Counter(b)

    # Check if we can transform b into a
    for key in count_a:
        if key not in count_b or count_a[key] > count_b[key]:
            return False

    # Check if we can reduce elements in b to match a
    for key in count_b:
        if key not in count_a:
            # Try to reduce key to a smaller value
            current = key
            while current % 2 == 0:
                current //= 2
                if current in count_a and count_b[key] - count_a[current] >= 0:
                    count_b[key] -= count_a[current]
                    if count_b[key] == 0:
                        del count_b[key]
                    break
            else:
                return False

    return True

